window.MG_LAZY_DATA["data/lazy/courses/c307-ea637a4e3e109850.json"]={sha256:"ea637a4e3e109850ec36ce864d8ddfd063189fd0701d9b648a4073f29104919f",value:{"id":"c307","title":"Landsat 地球觀測計畫","titleEn":"Landsat Earth-observation program","category":"space","summary":"以Landsat 8作主要儀器例子，學習軌道、波段、DN換算、品質遮罩與時間序列，區分原始觀測、處理结果及環境推論。","summaryEn":"Use Landsat 8 as the main instrument example to study orbit, bands, DN conversion, quality masks and time series, separating observations, processing and environmental inference.","scope":"12道原創遙測入門任務；課程沒有預載實景或實測表格。小算例係數為教學假設；實際分析需自行取得資料及其版本相符的中繼資料，不把单一衛星規格套用所有世代。","scopeEn":"Twelve original introductory remote-sensing tasks, without preloaded scenes or measured tables. Small-example coefficients are hypothetical. Actual analysis requires acquired data and matching metadata; one satellite’s specifications do not apply to every generation.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-landsat8","v6-landsat-level1","v6-eros-legacy","v6-video-0rVQHFPZfJk","v10-other-vendor-c307"],"diagram":{"type":"satellite","labels":["觀測需求","軌道與波段","影像與中繼資料","校準與遮罩","變化證據"],"labelsEn":["Observation needs","Orbit and bands","Imagery and metadata","Calibration and masks","Change evidence"],"original":true,"notToScale":true},"depth":4,"stages":[{"id":"c307-stage01","order":1,"title":"觀測設計與取樣尺度","titleEn":"Observation design and sampling scale","description":"從地表問題選擇時間、波段和空間尺度，再區分取樣與顯示。","descriptionEn":"Choose time, bands and spatial scale from the land question, then separate sampling from display.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c307-v6-01","order":1,"sequence":1,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":[],"sourceIds":["v6-landsat8"],"title":"把地表問題轉成觀測需求","titleEn":"Translate a land question into observation requirements","objective":"為植被比較選定波段、時段與品質條件。","objectiveEn":"Choose bands, periods and quality conditions for a vegetation comparison.","instruction":"設定虛構問題：同一地區兩個時段的植被是否改變？列出紅光、近紅外、可比日期、地理範圍及雲遮狀態；先定義資料需求，不把網站示意圖當作已下載影像。","instructionEn":"Set a fictional question: did vegetation change between two periods in one area? List red and near-infrared bands, comparable dates, geographic extent and cloud status. Define data requirements without treating site diagrams as downloaded imagery.","observation":"漂亮彩圖不代表兩期具備相同觀測條件。","observationEn":"An attractive color image does not establish comparable conditions between dates.","failure":"不同季節或雲遮的差異可能被錯認為地表變化。","failureEn":"Seasonal or cloud differences can be mistaken for surface change.","check":"每項比較需求都有資料欄位與排除條件。","checkEn":"Give each comparison requirement a data field and an exclusion condition.","knowledge":[{"id":"c307-v6-01-k1","title":"觀測設計","titleEn":"Observation design","text":"研究問題決定時間、波段與空間範圍。","textEn":"The question determines time, bands and spatial extent."},{"id":"c307-v6-01-k2","title":"可比性","titleEn":"Comparability","text":"比較之前需確認資料代表相近的觀測情境。","textEn":"Comparison first requires checking that observations represent compatible conditions."}],"quiz":{"question":"要比較植被變化，哪組條件較完整？","questionEn":"Which set is more complete for comparing vegetation change?","options":["使用同一衛星便不需核對季節與雲","像元間距相同便不需核對地點與日期","同地範圍、可比時段、紅光/NIR與雲狀態"],"optionsEn":["Use the same satellite without checking season or cloud","Match pixel spacing without checking location or date","Same area, comparable periods, red/NIR and cloud status"],"answer":2,"explanation":"資料的可比性比展示色彩更接近科學問題。","explanationEn":"Data comparability addresses the scientific question more directly than display colors."}},{"id":"c307-v6-02","order":2,"sequence":2,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-01"],"sourceIds":["v6-landsat8"],"title":"區分繞行週期與重訪週期","titleEn":"Distinguish orbital period from repeat cycle","objective":"避免把繞地球一圈當作回到同一觀測軌跡。","objectiveEn":"Avoid equating one orbit with a repeat of the same observation track.","instruction":"依USGS對Landsat 8的介紹，分別記錄約99分鐘繞行與16日重複週期。畫旋轉地球下的相鄰地面軌跡，說明為何兩種時間不能互換；不將數字套用全部Landsat世代。","instructionEn":"From USGS’s Landsat 8 overview, separately record the approximately 99-minute orbit and 16-day repeat cycle. Sketch adjacent tracks over a rotating Earth and explain why the intervals differ. Do not apply them to every Landsat generation.","observation":"衛星每圈經過不同地面經度，還需考慮地球自轉。","observationEn":"Successive orbits cross different ground longitudes because Earth rotates.","failure":"把99分鐘說成同一地點必定有新影像，混淆軌道與覆盖。","failureEn":"Claiming a new image of the same site every 99 minutes confuses orbit with coverage.","check":"筆記分開列出兩種週期、對應事件及Landsat 8限定。","checkEn":"Record both intervals, their events and the Landsat 8 limitation.","knowledge":[{"id":"c307-v6-02-k1","title":"地面軌跡","titleEn":"Ground track","text":"軌道運動與地球自轉共同決定地面投影。","textEn":"Orbital motion and Earth’s rotation jointly determine the ground projection."},{"id":"c307-v6-02-k2","title":"重訪與可用","titleEn":"Revisit and usability","text":"軌跡重訪也不保證無雲或符合研究需求。","textEn":"A repeated track does not guarantee cloud-free or suitable data."}],"quiz":{"question":"Landsat 8的99分鐘與16日分别描述什麼？","questionEn":"What do Landsat 8’s 99 minutes and 16 days describe?","options":["同地重訪與繞行一圈，順序與前項相反","繞行一圈與地面軌跡重複","資料處理時間與感測器曝光週期"],"optionsEn":["Site revisit and one orbit, in the reverse order","One orbit and ground-track repetition","Data processing duration and sensor exposure period"],"answer":1,"explanation":"不同週期對應不同幾何事件。","explanationEn":"The intervals describe different geometric events."}},{"id":"c307-v6-03","order":3,"sequence":3,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-02"],"sourceIds":["v6-landsat8"],"title":"閱讀多光譜波段的物理用途","titleEn":"Read the physical purposes of spectral bands","objective":"把感測波段與可觀察現象對應。","objectiveEn":"Relate spectral bands to observable phenomena.","instruction":"畫可見光、近紅外、短波紅外及熱紅外的概念區帶。將反射太陽光與熱放射分成兩類，再列植被、水分及熱狀態需要哪些額外判讀條件。","instructionEn":"Sketch conceptual visible, near-infrared, shortwave-infrared and thermal-infrared regions. Separate reflected sunlight from thermal emission, then list additional interpretation conditions for vegetation, moisture and thermal state.","observation":"不同波段不是相同照片換顏色，而是不同的光譜量測。","observationEn":"Bands are different spectral measurements, not the same photo recolored.","failure":"把熱紅外亮度直接當成可見光顏色，會用錯物理解釋。","failureEn":"Interpreting thermal-infrared brightness as visible color applies the wrong physics.","check":"至少把一個反射波段與一個熱波段對應到各自觀測機制。","checkEn":"Associate at least one reflected and one thermal band with their mechanisms.","knowledge":[{"id":"c307-v6-03-k1","title":"光譜選擇","titleEn":"Spectral selection","text":"感測器只量到其波段響應範圍內的資訊。","textEn":"A sensor measures information within its spectral response range."},{"id":"c307-v6-03-k2","title":"顯示與量測","titleEn":"Display versus measurement","text":"偽彩色把波段映射成螢幕色彩，不等於肉眼所見。","textEn":"False color maps bands to screen colors and need not match human vision."}],"quiz":{"question":"偽彩色中的紅色區域，必定是地表真實紅色嗎？","questionEn":"Must a red area in a false-color image be physically red?","options":["不一定，要查波段到色彩的映射","一定，每個顯示通道都等於相同的可見光顏色","只要像元更密，就可忽略波段映射"],"optionsEn":["No; inspect the band-to-color mapping","Yes; each display channel always equals the corresponding visible color","A denser pixel grid makes band mapping irrelevant"],"answer":0,"explanation":"顯示通道由使用者或產品設定。","explanationEn":"Display channels are set by the user or product."}},{"id":"c307-v6-04","order":4,"sequence":4,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-03"],"sourceIds":["v6-landsat8"],"title":"分開像元間距與可辨細節","titleEn":"Separate pixel spacing from resolved detail","objective":"理解取樣、混合像元與重取樣的差別。","objectiveEn":"Understand sampling, mixed pixels and resampling.","instruction":"在紙上畫30m網格與一條10m寬的假設河道，標出被河道和岸地共同占據的格子。再把網格細分成10m顯示格，指出哪些資訊仍無法由插值新增。","instructionEn":"Draw a 30 m grid and a hypothetical 10 m-wide river. Mark cells mixing water and banks, then subdivide the display grid to 10 m and identify information that interpolation cannot create.","observation":"更密的顯示格並不自動增加原始感測細節。","observationEn":"A denser display grid does not automatically add original sensor detail.","failure":"把輸出像元變小當作感測器解析度變高，會誇大辨識能力。","failureEn":"Treating smaller output pixels as better sensor resolution overstates resolving ability.","check":"指出一個混合像元，並註明重取樣只改資料表示。","checkEn":"Identify a mixed pixel and state that resampling changes representation.","knowledge":[{"id":"c307-v6-04-k1","title":"混合像元","titleEn":"Mixed pixel","text":"一個像元可能同時包含多種地表。","textEn":"One pixel may contain several surface types."},{"id":"c307-v6-04-k2","title":"取樣限制","titleEn":"Sampling limits","text":"後處理不能無條件恢復原始未量到的高頻資訊。","textEn":"Post-processing cannot unconditionally recover spatial information never measured."}],"quiz":{"question":"30m影像重取樣成10m格，能保證什麼？","questionEn":"Resampling a 30 m image to a 10 m grid guarantees what?","options":["新增真實10m感測細節","所有混合像元消失","輸出格網間距變小"],"optionsEn":["New genuine 10 m sensor detail","Removal of all mixed pixels","Smaller output-grid spacing"],"answer":2,"explanation":"格網間距與實際可辨識細節不同。","explanationEn":"Grid spacing differs from genuinely resolved detail."}}]},{"id":"c307-stage02","order":2,"title":"產品識別與物理換算","titleEn":"Product identity and physical conversion","description":"使用來源中的換算形式，搭配明示教學值與待填場景卡。","descriptionEn":"Use conversion forms from the references with explicit teaching values and pending scene cards.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c307-v6-05","order":1,"sequence":5,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-04"],"sourceIds":["v6-landsat-level1"],"title":"核對場景與中繼資料版本","titleEn":"Check scene and metadata identity","objective":"在轉換數值前確認資料產品與係數來源。","objectiveEn":"Confirm product and coefficient identity before conversion.","instruction":"建立一張空白場景卡，欄位含衛星、感測器、日期、產品層級、Collection、波段與中繼資料檔名。若自行從USGS取得資料，逐項抄錄；未取得時標為待填，不虛構場景編號。","instructionEn":"Create a blank scene card with satellite, sensor, date, product level, collection, band and metadata filename. If you obtain USGS data, transcribe them; otherwise mark fields pending rather than inventing a scene ID.","observation":"相同波段號碼在不同產品世代可能不代表相同用途。","observationEn":"The same band number can have different meaning across product generations.","failure":"拿另一場景或不同產品層級的係數換算，會失去可追溯性。","failureEn":"Using coefficients from another scene or product level breaks traceability.","check":"每項係數能連回同一產品的中繼資料，未知項明示。","checkEn":"Trace each coefficient to the same product’s metadata and mark unknowns.","knowledge":[{"id":"c307-v6-05-k1","title":"產品層級","titleEn":"Product level","text":"原始量化值與不同處理產品有不同解釋。","textEn":"Quantized values and differently processed products have different interpretations."},{"id":"c307-v6-05-k2","title":"參數溯源","titleEn":"Parameter provenance","text":"係數、版本與資料日期共同決定換算適用性。","textEn":"Coefficients, revision and date jointly determine conversion applicability."}],"quiz":{"question":"進行DN換算前，哪項最應先確認？","questionEn":"Before converting DN, what should be confirmed first?","options":["任意相鄰日期的係數都可直接沿用","係數屬於同一產品與波段","所有波段共用同一係數即可"],"optionsEn":["Coefficients from any nearby date can be reused directly","Coefficients belong to the same product and band","One coefficient set can be used for all bands"],"answer":1,"explanation":"正確公式搭配錯誤係數仍會得到錯誤結果。","explanationEn":"A correct formula with wrong coefficients still gives a wrong result."}},{"id":"c307-v6-06","order":2,"sequence":6,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-05"],"sourceIds":["v6-landsat-level1"],"title":"用教學係數換算輻亮度","titleEn":"Convert radiance using teaching coefficients","objective":"把DN與有物理單位的輻亮度分開。","objectiveEn":"Distinguish DN from radiance with physical units.","instruction":"使用USGS的線性形式L=M×DN+A，另設教學係數M=0.02、A=−1、DN=100，計算L。明寫係數虛構，實景必須使用該產品MTL檔的係數。","instructionEn":"Use the USGS linear form L=M×DN+A with invented teaching coefficients M=0.02, A=−1 and DN=100. Compute L and label the coefficients fictional; real scenes require their product’s MTL coefficients.","observation":"結果為1個相應輻亮度單位，不能把DN=100直接標作輻亮度。","observationEn":"The result is 1 in corresponding radiance units; DN=100 is not itself radiance.","failure":"漏掉加法項A，會得到不同且帶系統偏差的結果。","failureEn":"Omitting additive term A produces a systematic difference.","check":"保留乘法、加法與單位標記，且係數標為教學假設。","checkEn":"Retain multiplication, addition and units, with coefficients marked as assumptions.","knowledge":[{"id":"c307-v6-06-k1","title":"線性縮放","titleEn":"Linear scaling","text":"斜率與截距共同把量化值對應到物理量。","textEn":"Slope and intercept jointly map a quantized value to a physical quantity."},{"id":"c307-v6-06-k2","title":"資料解釋","titleEn":"Data interpretation","text":"儲存位元數不等於物理單位或精確度。","textEn":"Storage bit depth is not a physical unit or an accuracy guarantee."}],"quiz":{"question":"此例L=0.02×100−1等於多少？","questionEn":"What is L=0.02×100−1 in this example?","options":["1","2","100"],"optionsEn":["1","2","100"],"answer":0,"explanation":"乘法得2，再加−1得1。","explanationEn":"Multiplication gives 2; adding −1 gives 1."}},{"id":"c307-v6-07","order":3,"sequence":7,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-06"],"sourceIds":["v6-landsat-level1"],"title":"套用太陽角的反射率修正","titleEn":"Apply the solar-angle reflectance correction","objective":"區分未修正與太陽角修正的TOA反射率。","objectiveEn":"Separate uncorrected and solar-angle-corrected TOA reflectance.","instruction":"在紙上設未修正反射率ρ′=0.2、太陽高度30°，用ρ=ρ′/sin(θ)求值。另畫高度角與天頂角互補的圖；不把TOA反射率稱為地表反射率。","instructionEn":"Assume uncorrected reflectance ρ′=0.2 and solar elevation 30°, then apply ρ=ρ′/sin(θ). Sketch complementary elevation and zenith angles. Do not label TOA reflectance as surface reflectance.","observation":"本例sin30°=0.5，修正後為0.4。","observationEn":"Here sin30°=0.5, giving corrected reflectance 0.4.","failure":"混用高度角的cos與天頂角的sin，會套錯幾何。","failureEn":"Using cosine of elevation or sine of zenith applies the wrong geometry.","check":"同時標明角度定義、計算結果與TOA層級。","checkEn":"State the angle definition, result and TOA product level.","knowledge":[{"id":"c307-v6-07-k1","title":"角度定義","titleEn":"Angle definition","text":"太陽高度與天頂角互補，公式必須對應使用。","textEn":"Solar elevation and zenith are complementary, so formulas must match definitions."},{"id":"c307-v6-07-k2","title":"大氣層頂","titleEn":"Top of atmosphere","text":"太陽角修正不等於已消除所有大氣影響。","textEn":"Solar-angle correction does not remove every atmospheric effect."}],"quiz":{"question":"修正太陽高度後，能否直接稱為地表反射率？","questionEn":"After solar-elevation correction, can the result be called surface reflectance directly?","options":["能，太陽角修正已消除所有大氣影響","能，只要另外用了相同雲遮罩","不能，仍是TOA層級"],"optionsEn":["Yes; solar-angle correction removes every atmospheric effect","Yes, provided the same cloud mask is also used","No; it remains TOA reflectance"],"answer":2,"explanation":"幾何修正與大氣校正不同。","explanationEn":"Geometric correction differs from atmospheric correction."}},{"id":"c307-v6-08","order":4,"sequence":8,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-07"],"sourceIds":["v6-landsat8","v6-landsat-level1"],"title":"分辨亮溫與地表溫度","titleEn":"Distinguish brightness temperature from surface temperature","objective":"理解熱波段換算結果的物理層級。","objectiveEn":"Understand the physical level of a thermal-band conversion.","instruction":"畫熱放射從地表到感測器的路徑，列出放射率與大氣影響。閱讀USGS亮溫公式所需K1、K2及輻亮度欄位，建立空白計算表；無實景係數時不產生真實溫度地圖。","instructionEn":"Sketch thermal radiation traveling from surface to sensor and list emissivity and atmospheric effects. Identify K1, K2 and radiance required by the USGS brightness-temperature formula, creating a blank worksheet rather than a real temperature map without scene coefficients.","observation":"感測器亮溫不直接等於每一地物的實際表面溫度。","observationEn":"Sensor brightness temperature is not automatically the physical temperature of every surface.","failure":"忽略放射率或把K當°C，會造成不同類型的錯誤。","failureEn":"Ignoring emissivity or treating kelvin as Celsius creates different errors.","check":"表格清楚標K、產品層級及需另處理的環境因素。","checkEn":"Label kelvin, product level and environmental factors requiring further treatment.","knowledge":[{"id":"c307-v6-08-k1","title":"亮溫","titleEn":"Brightness temperature","text":"亮溫以輻射模型表達觀測到的熱訊號。","textEn":"Brightness temperature expresses an observed thermal signal through a radiative model."},{"id":"c307-v6-08-k2","title":"放射率","titleEn":"Emissivity","text":"不同表面的放射特性會影響溫度反推。","textEn":"Surface emission properties affect temperature inference."}],"quiz":{"question":"熱波段換出的亮溫要用於地表研究，還需注意什麼？","questionEn":"What still matters when using thermal brightness temperature for surface studies?","options":["只需從K值扣273.15就成為地表溫度","放射率、大氣與產品處理層級","同一熱波段的所有地物可共用相同放射特性"],"optionsEn":["Only subtract 273.15 from kelvin to obtain surface temperature","Emissivity, atmosphere and product-processing level","Every surface in one thermal band has the same emission properties"],"answer":1,"explanation":"亮溫與地表溫度具有不同假設。","explanationEn":"Brightness and surface temperature involve different assumptions."}}]},{"id":"c307-stage03","order":3,"title":"品質、對準與變化判讀","titleEn":"Quality, registration and change interpretation","description":"將遮罩、幾何、指標及跨感測器限制帶入可重現的比較。","descriptionEn":"Include masks, geometry, indices and cross-sensor limitations in reproducible comparisons.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c307-v6-09","order":1,"sequence":9,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-08"],"sourceIds":["v6-landsat8","v6-landsat-level1"],"title":"先遮罩再解讀有效像元","titleEn":"Mask before interpreting valid pixels","objective":"把雲、缺值與飽和等品質狀態保留在分析中。","objectiveEn":"Retain quality states such as cloud, missing data and saturation.","instruction":"自製一個3×3示意格，明確指定兩格雲、一格缺值，其餘為假設反射率。只對有效格計算平均，並記錄被排除數；真實產品須查其QA定義。","instructionEn":"Create a synthetic 3×3 grid with two cloud cells, one missing cell and assumed reflectance elsewhere. Average only valid cells and record exclusions; real products require their QA definitions.","observation":"有效像元數為6，不是9。","observationEn":"The valid-pixel count is 6, not 9.","failure":"把缺值當零加入平均，會人為降低結果。","failureEn":"Averaging missing data as zero artificially lowers the result.","check":"交付有效遮罩、平均分母與排除理由。","checkEn":"Provide the validity mask, averaging denominator and exclusion reasons.","knowledge":[{"id":"c307-v6-09-k1","title":"品質旗標","titleEn":"Quality flags","text":"品質資訊屬於資料解釋的一部分，而非可忽略附件。","textEn":"Quality information is part of data interpretation, not optional decoration."},{"id":"c307-v6-09-k2","title":"缺值語意","titleEn":"Missing-value meaning","text":"沒有觀測不等於觀測值為零。","textEn":"No observation is not an observed zero."}],"quiz":{"question":"9格中2格雲、1格缺值，平均分母應是多少？","questionEn":"With 2 cloudy and 1 missing cell among 9, what is the averaging denominator?","options":["6","9","3"],"optionsEn":["6","9","3"],"answer":0,"explanation":"排除三個無效觀測後剩六格。","explanationEn":"Excluding three invalid observations leaves six."}},{"id":"c307-v6-10","order":2,"sequence":10,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-09"],"sourceIds":["v6-landsat8"],"title":"核對兩期影像的幾何對準","titleEn":"Check registration between two dates","objective":"避免把位置錯位誤判為地表改變。","objectiveEn":"Avoid interpreting misregistration as surface change.","instruction":"畫兩張相同地物邊界的方格圖，讓第二張故意位移一格。做逐格差異標記，再恢復對準比較；說明真實資料還需核對投影、格網與重取樣方法。","instructionEn":"Draw two grid maps of identical boundaries and shift the second by one cell. Mark cellwise differences, then realign and compare. Explain that real data also require projection, grid and resampling checks.","observation":"位移能在邊緣製造一圈假變化。","observationEn":"A shift can create a band of false change around boundaries.","failure":"只檢查日期相近，卻未核對座標系，會留下空間錯配。","failureEn":"Checking similar dates without coordinate systems leaves spatial mismatch.","check":"列出對準前後差異，並標示共同格網基準。","checkEn":"Report differences before and after alignment and label the shared grid.","knowledge":[{"id":"c307-v6-10-k1","title":"配準","titleEn":"Registration","text":"比較像元需要代表相同或可對應的地面位置。","textEn":"Compared pixels must represent the same or corresponding ground locations."},{"id":"c307-v6-10-k2","title":"邊緣敏感性","titleEn":"Edge sensitivity","text":"地物邊界對小位移通常比均勻區域更敏感。","textEn":"Boundaries are usually more sensitive to small shifts than uniform areas."}],"quiz":{"question":"差異只集中在所有地物邊緣，優先檢查什麼？","questionEn":"Differences cluster around every boundary. What should be checked first?","options":["直接認定所有地物都同時發生邊緣變化","先對兩期影像各自加強銳化","影像配準與格網"],"optionsEn":["Assume every feature experienced simultaneous boundary change","First sharpen each date independently","Image registration and grids"],"answer":2,"explanation":"規律邊缘差異可能來自幾何錯位。","explanationEn":"Systematic edge differences may arise from geometric misregistration."}},{"id":"c307-v6-11","order":3,"sequence":11,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-10"],"sourceIds":["v6-landsat8","v6-landsat-level1"],"title":"計算並限制植被指標的結論","titleEn":"Calculate a vegetation index and limit its interpretation","objective":"用簡單比值連接波段，同時保留限制。","objectiveEn":"Connect bands with a simple ratio while retaining limitations.","instruction":"使用教學反射率NIR=0.6、Red=0.2，計算NDVI=(NIR−Red)/(NIR+Red)。再用NIR=Red=0討論分母問題；先確認兩波段同層級、同位置且有效。","instructionEn":"Use teaching reflectances NIR=0.6 and Red=0.2 to calculate NDVI=(NIR−Red)/(NIR+Red). Then consider NIR=Red=0 and the denominator problem. First ensure both bands share processing level, location and validity.","observation":"例題NDVI為0.5，但無法僅凭這個數值指定植物種類。","observationEn":"The example NDVI is 0.5, but that value alone cannot identify a plant species.","failure":"不同單位或無效像元直接相除，会得到無法解釋的指標。","failureEn":"Combining inconsistent units or invalid pixels produces an uninterpretable index.","check":"保存算式、有效性條件與至少一項不能支持的結論。","checkEn":"Retain the calculation, validity conditions and at least one unsupported conclusion.","knowledge":[{"id":"c307-v6-11-k1","title":"正規化差值","titleEn":"Normalized difference","text":"分子表示波段差，分母提供尺度正規化。","textEn":"The numerator expresses a band difference and the denominator normalizes scale."},{"id":"c307-v6-11-k2","title":"指標非診斷","titleEn":"Index is not a diagnosis","text":"指標是線索，仍需環境、時間及地面證據。","textEn":"An index is evidence to interpret alongside environment, time and ground information."}],"quiz":{"question":"NIR=0.6、Red=0.2時NDVI為何？","questionEn":"What is NDVI for NIR=0.6 and Red=0.2?","options":["2","0.5","0.8"],"optionsEn":["2","0.5","0.8"],"answer":1,"explanation":"(0.6−0.2)/(0.6+0.2)=0.4/0.8=0.5。","explanationEn":"(0.6−0.2)/(0.6+0.2)=0.4/0.8=0.5."}},{"id":"c307-v6-12","order":4,"sequence":12,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c307-v6-11"],"sourceIds":["v6-landsat8","v6-landsat-level1","v6-eros-legacy"],"title":"整理長期序列的校準證據","titleEn":"Organize calibration evidence for a long-term series","objective":"把真實地表變化與感測器、處理變化分開。","objectiveEn":"Separate surface change from sensor and processing changes.","instruction":"建立跨三期的空白比較表，列衛星、波段定義、產品版本、雲遮、幾何對準及處理步驟。若不同感測器的波段響應不完全相同，將可比性列為需驗證，不自行宣布趨勢成立。","instructionEn":"Create a three-period comparison table with satellite, band definition, product revision, cloud, registration and processing steps. If sensor band responses differ, mark comparability for verification rather than declaring a trend.","observation":"產品值可換算到相同單位，仍可能受光譜響應差異影響。","observationEn":"Values in common units can still differ because spectral responses differ.","failure":"把處理版本改變造成的階躍當作環境突變，會誤導長期結論。","failureEn":"A processing-revision discontinuity can be misread as an environmental event.","check":"交付可重現的資料清單與限制，不虛構已取得的Landsat實景。","checkEn":"Deliver a reproducible data inventory and limitations without implying actual scenes were acquired.","knowledge":[{"id":"c307-v6-12-k1","title":"跨感測器比較","titleEn":"Cross-sensor comparison","text":"相同波段名稱不保證完全相同的光譜響應。","textEn":"Matching band names do not guarantee identical spectral responses."},{"id":"c307-v6-12-k2","title":"重現性","titleEn":"Reproducibility","text":"資料版本、係數與處理順序應一併保留。","textEn":"Retain data revisions, coefficients and processing order together."}],"quiz":{"question":"時間序列突變剛好遇到產品版本更新，應先做什麼？","questionEn":"A time-series jump coincides with a product update. What should be done first?","options":["檢查處理與校準差異再判讀環境","直接宣布地表突然變化","先將新版數值全部平移到舊資料平均值"],"optionsEn":["Check processing and calibration differences before environmental interpretation","Immediately declare abrupt surface change","Shift all new-product values to the old mean before investigation"],"answer":0,"explanation":"觀測與處理鏈的變化是需排除的替代解釋。","explanationEn":"Changes in observation and processing are alternative explanations to evaluate."}}]}],"stepCount":12,"estimatedMinutes":216,"languageCoverage":["zh-TW","en"],"status":"guided","kind":"course","curriculumVersion":6}};
